// Base Notation
int dec = 42;
int oct = 052;          // Octal (0 prefix)
int hex = 0x2A;         // Hex (0x prefix)
int bin = 0b101010;     // C++14 Binary (0b prefix)

// Type Suffixes (Case insensitive)
auto u_val = 100U;      // unsigned int
auto l_val = 100L;      // long
auto ull_val = 100ULL;  // unsigned long long

// Literal type rules: Smallest type that fits (int, long, long long)
auto big_val = 3000000000; // Likely long or long long (platform dependent)

// C++14 Digit Separators (any base)
int large_num = 1'000'000;
long reg_addr = 0xDE'AD'BEEF;
// unsigned long: 0xDEADBEEFUL;
